  else
    started <= started0;
assign started0 = ~sop_temp & (started | enable);
assign ops2 = ops | ({PORTSIZE_ops{enable}} & (~(starts)));
assign or_temp = current | ops2;
assign sop_temp = reduce_INs(or_temp);
assign sop = sop_temp;
always @ (posedge clock 1RESET_EDGE)
begin
if(1RESET_VALUE)
  begin
    current <= {PORTSIZE_ops{1'b0}};
  end
else
  begin
    current <= NEXT_CURR(sop_temp,ops2,current,started0);
  end
end
